SELECT `id`, `call_session_id`, `event_type`, `source`, `provider_event_key`, `repeat_count`, `created_at` FROM `webhookeventingest`
WHERE EXISTS (SELECT 1 FROM `callsession` p WHERE p.`id` = `webhookeventingest`.`call_session_id` AND p.`tenant_id` = #{tenantId,jdbcType=INTEGER})
ORDER BY `id` LIMIT #{limit,jdbcType=INTEGER} OFFSET #{offset,jdbcType=INTEGER}
